const raw = {
  id: "cdk-instance", type: "instance", name: "cdk-instance",
  labels: { bRaNcH: "feat-ledger", TEAM: "Payments" },
};

test("envctl preserves CDK ownership without changing shared client conversion", () => {
  assert.deepEqual(toResource(raw).tags, {});
  const r = resourceFromProvider(raw);
  assert.equal(branchOf(r), "feat-ledger");
  assert.equal(isUntagged(r), false);
  assert.equal(byBranch([r]).get("feat-ledger")?.length, 1);
  assert.ok(matches(r, [["team", "Payments"]]));
  assert.ok(!matches(r, [["team", "payments"]]));
  assert.equal(buildPlan([r], "FEAT-LEDGER").steps.length, 0);
});

test("legacy tags take precedence over labels and absent metadata stays untagged", () => {
  const r = resourceFromProvider({ ...raw, tags: { branch: "feat-other", owner: "payments" } });
  assert.equal(branchOf(r), "feat-other");
  assert.ok(matches(r, [["owner", "payments"], ["team", "Payments"]]));
  assert.ok(isUntagged(resourceFromProvider({ id: "manual" })));
  assert.ok(isUntagged(resourceFromProvider({ id: "manual", tags: null, labels: null })));
});

test("label ownership includes stack companions but not other branches or prefix stacks", () => {
  const resources = [
    resourceFromProvider({ ...raw, stack_id: "custom-stack" }),
    resourceFromProvider({ id: "boot", stack_id: "custom-stack" }),
    resourceFromProvider({ id: "canonical", stack_id: "stk-feat-ledger" }),
    resourceFromProvider({ id: "v2", stack_id: "stk-feat-ledger-v2" }),
    resourceFromProvider({ id: "other", stack_id: "custom-stack", labels: { Branch: "feat-other" } }),
    resourceFromProvider({ id: "manual" }),
  ];
  assert.deepEqual(buildPlan(resources, "feat-ledger").steps.map(s => s.id).sort(),
    ["boot", "canonical", "cdk-instance"]);
});
