import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { createServer } from "node:http";
import { once } from "node:events";
import { test } from "node:test";
import type { AddressInfo } from "node:net";

type RawResource = Record<string, unknown> & { id: string; depends_on?: string[] };
const resource = (id: string, metadata: Record<string, unknown> = {}, depends_on: string[] = []): RawResource => ({
  id, type: "instance", name: id, cost_month_cents: 100, depends_on, ...metadata,
});

async function fixture(external = false) {
  // Ownership metadata occurs on both sides of a real 20-resource page boundary.
  const resources = [
    resource("network", { tags: { branch: "feat-ledger" }, stack_id: "stk-feat-ledger" }),
    ...Array.from({ length: 19 }, (_, i) => resource(`other-${i}`, { tags: { branch: "feat-other" } })),
    resource("boot", { stack_id: "stk-feat-ledger" }),
    resource("cdk-volume", { labels: { BRANCH: "feat-ledger" } }),
    resource("cdk-instance", { labels: { Branch: "feat-ledger", Team: "payments" } }, ["network", "boot", "cdk-volume"]),
    resource("cdk-dns", { labels: { branch: "feat-ledger" } }, ["cdk-instance"]),
    resource("v2", { stack_id: "stk-feat-ledger-v2", tags: { branch: "feat-ledger-v2" } }),
    resource("manual"),
    ...(external ? [resource("external", { labels: { Branch: "feat-other" } }, ["network"])] : []),
  ];
  const deleted: string[] = [];
  const cursors: string[] = [];
  const server = createServer((req, res) => {
    assert.equal(req.headers.authorization, "Bearer test-token");
    res.setHeader("content-type", "application/json");
    const url = new URL(req.url!, "http://localhost");
    if (req.method === "GET" && url.pathname === "/v1/resources") {
      const cursor = url.searchParams.get("cursor")!;
      cursors.push(cursor);
      assert.equal(url.searchParams.get("limit"), "20");
      const start = Number(cursor);
      res.end(JSON.stringify({ resources: resources.slice(start, start + 20),
        next_cursor: start + 20 < resources.length ? String(start + 20) : null }));
    } else if (req.method === "DELETE") {
      const id = decodeURIComponent(url.pathname.slice("/v1/resources/".length));
      const dependents = resources.filter(r => r.depends_on?.includes(id));
      if (dependents.length) {
        res.statusCode = 409;
        res.end(JSON.stringify({ error: "resource has dependents", dependents: dependents.map(r => r.id) }));
      } else {
        const index = resources.findIndex(r => r.id === id);
        assert.notEqual(index, -1);
        resources.splice(index, 1);
        deleted.push(id);
        res.end(JSON.stringify({ deleted: id }));
      }
    } else {
      res.statusCode = 404;
      res.end(JSON.stringify({ error: "not found" }));
    }
  });
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  const baseUrl = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  return {
    resources, deleted, cursors,
    close: () => new Promise<void>((resolve, reject) => server.close(err => err ? reject(err) : resolve())),
    run: async (...args: string[]) => {
      const child = spawn(process.execPath, ["--experimental-strip-types", "--no-warnings", "src/cli.ts", ...args], {
        env: { ...process.env, ENVCTL_API: baseUrl, ENVCTL_TOKEN: "test-token" },
        stdio: ["ignore", "pipe", "pipe"],
      });
      let stdout = "", stderr = "";
      child.stdout.on("data", data => { stdout += data; });
      child.stderr.on("data", data => { stderr += data; });
      const [code] = await once(child, "close");
      return { code, stdout, stderr };
    },
  };
}

test("CLI uses labels on every page for plan, list, GC and dependency-safe teardown", async () => {
  const f = await fixture();
  try {
    const planned = await f.run("plan", "--branch", "feat-ledger", "--json");
    assert.equal(planned.code, 0, planned.stderr);
    const plan = JSON.parse(planned.stdout);
    const targetIds = ["network", "boot", "cdk-volume", "cdk-instance", "cdk-dns"];
    assert.deepEqual(plan.steps.map((s: { id: string }) => s.id).sort(), targetIds.toSorted());
    assert.deepEqual(plan.blocked, []);
    assert.deepEqual(f.cursors, ["0", "20"]);

    const listed = await f.run("list");
    assert.equal(listed.code, 0, listed.stderr);
    assert.match(listed.stdout, /feat-ledger\s+4\s/);
    const gc = await f.run("gc", "--untagged");
    assert.equal(gc.code, 0, gc.stderr);
    assert.match(gc.stdout, /^2 untagged resources/); // stack boot + truly manual
    const dryRun = await f.run("teardown", "--branch", "feat-ledger", "--dry-run");
    assert.equal(dryRun.code, 0, dryRun.stderr);
    assert.deepEqual(f.deleted, []);

    const tornDown = await f.run("teardown", "--branch", "feat-ledger");
    assert.equal(tornDown.code, 0, tornDown.stderr);
    assert.deepEqual(f.deleted.toSorted(), targetIds.toSorted());
    const pos = (id: string) => f.deleted.indexOf(id);
    assert.ok(pos("cdk-dns") < pos("cdk-instance"));
    for (const dependency of ["network", "boot", "cdk-volume"]) assert.ok(pos("cdk-instance") < pos(dependency));
    assert.equal(f.resources.length, 21); // all unrelated resources survived
    const after = await f.run("plan", "--branch", "feat-ledger", "--json");
    assert.equal(after.code, 0, after.stderr);
    assert.deepEqual(JSON.parse(after.stdout).steps, []);
  } finally {
    await f.close();
  }
});

test("CLI still refuses teardown when a label-owned external resource depends on the branch", async () => {
  const f = await fixture(true);
  try {
    const planned = await f.run("plan", "--branch", "feat-ledger", "--json");
    assert.equal(planned.code, 0, planned.stderr);
    assert.deepEqual(JSON.parse(planned.stdout).blocked, [{ id: "network", dependents: ["external"] }]);
    const result = await f.run("teardown", "--branch", "feat-ledger");
    assert.equal(result.code, 1);
    assert.match(result.stderr, /refusing to tear down/);
    assert.deepEqual(f.deleted, []);
  } finally {
    await f.close();
  }
});
